import subprocess
branches=["friend/rachel","friend/monica","friend/phoebe","friend/joey","friend/chandler","friend/ross"]
transcript=set()
import re
files=subprocess.check_output(["git","ls-tree","-r","--name-only","origin/main"],text=True).split()
for f in files:
    if re.fullmatch(r"S\d+/E\d+\.md",f):
        txt=subprocess.check_output(["git","show",f"origin/main:{f}"],text=True)
        for line in txt.splitlines():
            if line.startswith("Source: "):
                transcript.add(line.split("@",1)[1].strip())
commits=[]
for b in branches:
    out=subprocess.check_output(["git","log","--format=%H%x1f%ci%x1f%B%x1e",f"origin/{b}"], text=True)
    for chunk in out.split('\x1e'):
        if not chunk.strip(): continue
        parts=chunk.split('\x1f',2)
        if len(parts)<3: continue
        sha,ci,body=parts
        sha=sha.strip(); ci=ci.strip()
        if "Friend-Message: 1" not in body: continue
        ep=None
        for line in body.splitlines():
            if line.startswith("Episode:"):
                ep=line.split(":",1)[1].strip()
        if sha not in transcript:
            commits.append((ci,sha,b,ep,body.strip()))
commits.sort(key=lambda x:(x[0],x[1]))
for ci,sha,b,ep,body in commits:
    print("====",ci,sha,b,"EP=",repr(ep))
    print(body)
